import{_ as i,a0 as l,w as r,s as o,ao as d,I as t,x as n,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"漫谈传统的 Linux 初始化系统的运行级别 | LCTT x X-CMD","titleTemplate":false,"description":"漫谈传统的 Linux 初始化系统的运行级别 | LCTT (201709) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"漫谈传统的 Linux 初始化系统的运行级别 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"漫谈传统的 Linux 初始化系统的运行级别 | LCTT (201709) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201709/20170905 Maneuvering around run levels on Linux","title":"漫谈传统的 Linux 初始化系统的运行级别","tag":"201709","desc":""},"relativePath":"201709/20170905 Maneuvering around run levels on Linux.md","filePath":"[post].md"}'),c={name:"201709/20170905 Maneuvering around run levels on Linux.md"};function g(u,s,h,x,k,b){const a=l("Link");return r(),o("div",null,[s[18]||(s[18]=d(`<h1 id="漫谈传统的-linux-初始化系统的运行级别" tabindex="-1">漫谈传统的 Linux 初始化系统的运行级别 <a class="header-anchor" href="#漫谈传统的-linux-初始化系统的运行级别" aria-label="Permalink to “漫谈传统的 Linux 初始化系统的运行级别”">​</a></h1><blockquote><p>了解运行级别是如何配置的，如何改变系统运行级别以及修改对应状态下运行的服务。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2017/09/run-levels-vincent_desjardins-100734685-large.jpg" alt="操作 Linux 的运行级别"></p><p>在 Linux 系统中，<ruby>运行级别<rt>run level</rt></ruby>是指运维的级别，用于描述一种表明什么服务是可用的系统运行状态。</p><p>运行级别 1 是严格限制的，仅仅用于系统维护；该级别下，网络连接将不可操作，但是管理员可以通过控制台连接登录系统。</p><p>其他运行级别的系统允许任何人登录和使用，但是不同级别中可使用的服务不同。本文将探索如何配置运行级别，如何交互式改变系统运行级别以及修改该状态下可用的服务。</p><p>Linux 系统的默认运行状态是一个在系统开机时使用的运行级别（除非有其他的指示），它通常是在 <code>/etc/inittab</code> 文件中进行配置的，该文件内容通常如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>id:3:initdefault</span></span></code></pre></div><p>包括 Debian 系统在内的一些系统，默认运行级别为 2，而不是上述文件中的 3，甚至都没有 <code>/etc/inittab</code> 文件。</p><p>运行级别在默认情况下是如何被配置，其配置依赖于你所运行的 Linux 操作系统的具体发行版本。 例如，在某些系统中， 运行级别 2 是多用户模式，运行级别 3 是多用户模式并支持 NFS （网络文件系统）。 在另外一些系统，运行级别 2 - 5 基本相同，运行级别 1 是单用户模式。例如，Debian 系统的所用运行级别如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 = 停机</span></span>
<span class="line"><span>1 = 单用户（维护模式）</span></span>
<span class="line"><span>2 = 多用户模式</span></span>
<span class="line"><span>3-5 = 同 2 一样</span></span>
<span class="line"><span>6 = 重启</span></span></code></pre></div><p>在 Linux 系统上，运行级别 3 用于共享文件系统给其它系统，可以方便地只通过改变系统的运行级别来启动和停止文件系统共享。系统从运行级别 2 改变到 3 系统将允许文件系统共享，反之从运行级别 3 改变到 2 则系统不支持文件系统共享。</p><p>在某个运行级别中，系统运行哪些进程依赖于目录 <code>/etc/rc?.d</code> 目录的内容，其中 <code>?</code> 可以是 2、 3、 4 或 5 （对应于相应的运行级别）。</p><p>在以下示例中（Ubuntu 系统），由于这些目录的配置是相同的，我们将看见上述 4 个级别对应的目录中的内容是一致的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/etc/rc2.d$ ls</span></span>
<span class="line"><span>README         S20smartmontools      S50saned      S99grub-common</span></span>
<span class="line"><span>S20kerneloops  S20speech-dispatcher  S70dns-clean  S99ondemand</span></span>
<span class="line"><span>S20rsync       S20sysstat            S70pppd-dns   S99rc.local</span></span>
<span class="line"><span>/etc/rc2.d$ cd ../rc3.d</span></span>
<span class="line"><span>/etc/rc3.d$ ls</span></span>
<span class="line"><span>README         S20smartmontools      S50saned      S99grub-common</span></span>
<span class="line"><span>S20kerneloops  S20speech-dispatcher  S70dns-clean  S99ondemand</span></span>
<span class="line"><span>S20rsync       S20sysstat            S70pppd-dns   S99rc.local</span></span>
<span class="line"><span>/etc/rc3.d$ cd ../rc4.d</span></span>
<span class="line"><span>/etc/rc4.d$ ls</span></span>
<span class="line"><span>README         S20smartmontools      S50saned      S99grub-common</span></span>
<span class="line"><span>S20kerneloops  S20speech-dispatcher  S70dns-clean  S99ondemand</span></span>
<span class="line"><span>S20rsync       S20sysstat            S70pppd-dns   S99rc.local</span></span>
<span class="line"><span>/etc/rc4.d$ cd ../rc5.d</span></span>
<span class="line"><span>/etc/rc5.d$ ls</span></span>
<span class="line"><span>README         S20smartmontools      S50saned      S99grub-common</span></span>
<span class="line"><span>S20kerneloops  S20speech-dispatcher  S70dns-clean  S99ondemand</span></span>
<span class="line"><span>S20rsync       S20sysstat            S70pppd-dns   S99rc.local</span></span></code></pre></div><p>这些都是什么文件？它们都是指向 <code>/etc/init.d</code> 目录下用于启动服务的脚本符号连接。 这些文件的文件名是至关重要的， 因为它们决定了这些脚本文件的执行顺序，例如, S20 脚本是在 S50 脚本前面运行的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l</span></span>
<span class="line"><span>total 4</span></span>
<span class="line"><span>-rw-r--r-- 1 root root 677 Feb 16  2016 README</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  20 Aug 30 14:40 S20kerneloops -&gt; ../init.d/kerneloops</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  15 Aug 30 14:40 S20rsync -&gt; ../init.d/rsync</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  23 Aug 30 16:10 S20smartmontools -&gt; ../init.d/smartmontools</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  27 Aug 30 14:40 S20speech-dispatcher -&gt; ../init.d/speech-dispatcher</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  17 Aug 31 14:12 S20sysstat -&gt; ../init.d/sysstat</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  15 Aug 30 14:40 S50saned -&gt; ../init.d/saned</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  19 Aug 30 14:40 S70dns-clean -&gt; ../init.d/dns-clean</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  18 Aug 30 14:40 S70pppd-dns -&gt; ../init.d/pppd-dns</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  21 Aug 30 14:40 S99grub-common -&gt; ../init.d/grub-common</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  18 Aug 30 14:40 S99ondemand -&gt; ../init.d/ondemand</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  18 Aug 30 14:40 S99rc.local -&gt; ../init.d/rc.local</span></span></code></pre></div><p>如你所想，目录 <code>/etc/rc1.d</code> 因运行级别 1 的特殊而不同。它包含的符号链接指向非常不同的一套脚本。 同样也要注意到其中一些脚本以 <code>K</code> 开头命名，而另一些与其它运行级别脚本一样以 <code>S</code> 开头命名。这是因为当系统进入单用户模式时， 一些服务需要<strong>停止</strong>。 然而这些 K 开头的符号链接指向了其它级别 S 开头的符号链接的同一文件时， K（kill）表示这个脚本将以指示其停止的参数执行，而不是以启动的参数执行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/etc/rc1.d$ ls -l</span></span>
<span class="line"><span>total 4</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  20 Aug 30 14:40 K20kerneloops -&gt; ../init.d/kerneloops</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  15 Aug 30 14:40 K20rsync -&gt; ../init.d/rsync</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  15 Aug 30 14:40 K20saned -&gt; ../init.d/saned</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  23 Aug 30 16:10 K20smartmontools -&gt; ../init.d/smartmontools</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  27 Aug 30 14:40 K20speech-dispatcher -&gt; ../init.d/speech-dispatcher</span></span>
<span class="line"><span>-rw-r--r-- 1 root root 369 Mar 12  2014 README</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  19 Aug 30 14:40 S30killprocs -&gt; ../init.d/killprocs</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  19 Aug 30 14:40 S70dns-clean -&gt; ../init.d/dns-clean</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  18 Aug 30 14:40 S70pppd-dns -&gt; ../init.d/pppd-dns</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  16 Aug 30 14:40 S90single -&gt; ../init.d/single</span></span></code></pre></div><p>你可以改变系统的默认运行级别，尽管这很少被用到。例如，通过修改前文中提到的 <code>/etc/inittab</code> 文件，你能够配置 Debian 系统的默认运行级别为 3 （而不是 2），以下是该文件示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>id:3:initdefault:</span></span></code></pre></div><p>一旦你修改完成并重启系统， <code>runlevel</code> 命令将显示如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ runlevel</span></span>
<span class="line"><span>N 3</span></span></code></pre></div><p>另外一种可选方式，使用 <code>init 3</code> 命令，你也能改变系统运行级别（且无需重启立即生效）， <code>runlevel</code> 命令的输出为：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ runlevel</span></span>
<span class="line"><span>2 3</span></span></code></pre></div><p>当然，除非你修改了系统默认级别的 <code>/etc/rc?.d</code> 目录下的符号链接，使得系统默认运行在一个修改的运行级别之下，否则很少需要通过创建或修改 <code>/etc/inittab</code> 文件改变系统的运行级别。</p><h3 id="在-linux-系统中如何使用运行级别" tabindex="-1">在 Linux 系统中如何使用运行级别？ <a class="header-anchor" href="#在-linux-系统中如何使用运行级别" aria-label="Permalink to “在 Linux 系统中如何使用运行级别？”">​</a></h3><p>为了扼要重述在系统中如何使用运行级别，下面有几个关于运行级别的快速问答问题：</p><p><strong>如何查询系统当前的运行级别？</strong></p><p>使用 <code>runlevel</code> 命令。</p><p><strong>如何查看特定运行级别所关联的服务进程？</strong></p><p>查看与该运行级别关联的运行级别开始目录（例如， <code>/etc/rc2.d</code> 对应于运行级别 2）。</p><p><strong>如何查看系统的默认运行级别？</strong></p><p>首先，查看 <code>/etc/inittab</code> 文件是否存在。如果不存在，就执行 <code>runlevel</code> 命令查询，你一般就已经处在该运行级别。</p><p><strong>如何改变系统运行级别？</strong></p><p>用 <code>init</code> 命令（例如 <code>init 3</code>）临时改变运行级别，通过修改或创建 <code>/etc/inittab</code> 文件永久改变其运行级别。</p><p><strong>能改变特定运行级别下运行的服务么？</strong></p><p>当然，通过改变对应的 <code>/etc/rc?.d</code> 目录下的符号连接即可。</p><p><strong>还有一些其他的什么需要考虑？</strong></p><p>当改变系统运行级别时，你应该特别小心，确保不影响到系统上正在运行的服务或者正在使用的用户。</p>`,40)),t("p",null,[s[2]||(s[2]=n("（题图：",-1)),e(a,{href:"https://www.flickr.com/photos/endymion120/4824696883/in/photolist-8mkQi2-8vtyRx-8vvYZS-i31xQj-4TXTS2-S7VRNC-azimYK-dW8cYu-Sb5b7S-S7VRES-fpSVvo-61Zpn8-WxFwGi-UKKq3x-q6NSnC-8vsBLr-S3CPxn-qJUrLr-nDnpNu-8d7a6Q-T7mGpN-RE26wj-SeEXRa-5mZ7LG-Vp7t83-fEG5HS-Vp7sU7-6JpNBi-RCuR8P-qLzCL5-6WsfZx-5nU1tF-6ieGFi-3P5xwh-8mnxpo-hBXwSj-i3iCur-9dmrST-6bXk8d-8vtDb4-i2KLwU-5jhfU6-8vwbrN-ShAtNm-XgzXmb-8rad18-VfXm4L-8tQTrh-Vp7tcb-UceVDB"},{default:p(()=>[...s[0]||(s[0]=[n("Vincent Desjardins",-1)])]),_:1}),s[3]||(s[3]=n()),e(a,{href:"https://creativecommons.org/licenses/by/2.0/legalcode"},{default:p(()=>[...s[1]||(s[1]=[n("(CC BY 2.0)",-1)])]),_:1}),s[4]||(s[4]=n("）",-1))]),s[19]||(s[19]=t("hr",null,null,-1)),t("p",null,[s[6]||(s[6]=n("via: ",-1)),e(a,{href:"https://www.networkworld.com/article/3222070/linux/maneuvering-around-run-levels-on-linux.html"},{default:p(()=>[...s[5]||(s[5]=[n("https://www.networkworld.com/article/3222070/linux/maneuvering-around-run-levels-on-linux.html",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=n("作者：",-1)),e(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:p(()=>[...s[7]||(s[7]=[n("Sandra Henry-Stocker",-1)])]),_:1}),s[11]||(s[11]=n(" 译者：",-1)),e(a,{href:"https://github.com/penghuster"},{default:p(()=>[...s[8]||(s[8]=[n("penghuster",-1)])]),_:1}),s[12]||(s[12]=n(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:p(()=>[...s[9]||(s[9]=[n("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[13]||(s[13]=[n("LCTT",-1)])]),_:1}),s[16]||(s[16]=n(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:p(()=>[...s[14]||(s[14]=[n("Linux中国",-1)])]),_:1}),s[17]||(s[17]=n(" 荣誉推出",-1))])])}const f=i(c,[["render",g]]);export{S as __pageData,f as default};
